{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.aged_inventory_liquidation as WITH base AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group FROM snitch_db.maplemonk.logic_purchase_order WHERE sku_group IS NOT NULL ), flagged_skus AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group FROM snitch_db.maplemonk.bad_inventory_sku WHERE sku_group IS NOT NULL ), product AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' OR UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(\"Item Type skuCode\")) END END AS sku_group, DATEDIFF( day, MIN(TRY_TO_DATE(PUTAWAY_COMPLETED_DATE)), CURRENT_DATE() ) AS DAYS_SINCE_INWARD FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(TRIM(final_type)) = \'new inward\' AND PUTAWAY_COMPLETED_DATE IS NOT NULL GROUP BY 1 ), category_data AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, L1_CATEGORY, CATEGORY FROM SNITCH_DB.MAPLEMONK.CATEGORY_OVERALL_DATA ), inventory_union AS ( SELECT \"Item SkuCode\", \'good_inventory\' AS inventory_status, UPPER(TRIM(facility)) AS inventory_location, INVENTORY AS inventory_qty, COALESCE(\"Inventory Blocked\", 0) AS \"Inventory Blocked\", COALESCE(\"Bad Inventory\", 0) AS \"Bad Inventory\", COALESCE(\"Inventory Not Synced\", 0) AS \"Inventory Not Synced\", COALESCE(\"Stock In Transfer\", 0) AS \"Stock In Transfer\", COALESCE(\"Not Found\", 0) AS \"Not Found\", COALESCE(\"Open Purchase\", 0) AS \"Open Purchase\", COALESCE(\"Open Sale\", 0) AS \"Open Sale\", COALESCE(\"Pending Inventory Assessment\", 0) AS \"Pending Inventory Assesment\" FROM snitch_db.maplemonk.UNICOMMERCE_LIVE_INVENTORY WHERE COALESCE(INVENTORY, 0) <> 0 UNION ALL SELECT \"Item SkuCode\", \'bad_inventory\' AS inventory_status, UPPER(TRIM(facility)) AS inventory_location, \"Bad Inventory\" AS inventory_qty, COALESCE(\"Inventory Blocked\", 0) AS \"Inventory Blocked\", COALESCE(\"Bad Inventory\", 0) AS \"Bad Inventory\", COALESCE(\"Inventory Not Synced\", 0) AS \"Inventory Not Synced\", COALESCE(\"Stock In Transfer\", 0) AS \"Stock In Transfer\", COALESCE(\"Not Found\", 0) AS \"Not Found\", COALESCE(\"Open Purchase\", 0) AS \"Open Purchase\", COALESCE(\"Open Sale\", 0) AS \"Open Sale\", COALESCE(\"Pending Inventory Assessment\", 0) AS \"Pending Inventory ASSESMENT\" FROM snitch_db.maplemonk.UNICOMMERCE_LIVE_INVENTORY WHERE COALESCE(\"Bad Inventory\", 0) <> 0 UNION ALL SELECT sku_group AS \"Item SkuCode\", \'good_inventory\' AS inventory_status, \'STORE\' AS inventory_location, inventory AS inventory_qty, 0 AS \"Inventory Blocked\", 0 AS \"Bad Inventory\", 0 AS \"Inventory Not Synced\", 0 AS \"Stock In Transfer\", 0 AS \"Not Found\", 0 AS \"Open Purchase\", 0 AS \"Open Sale\", 0 AS \"Pending Inventory Adjustment\" FROM snitch_db.maplemonk.offline_master WHERE COALESCE(inventory, 0) <> 0 ), inventory AS ( SELECT CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SN%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item SkuCode\")) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(\"Item SkuCode\")) END END AS sku_group, inventory_status, inventory_location, SUM(inventory_qty) AS inventory, SUM(\"Inventory Blocked\") AS \"Inventory Blocked\", SUM(\"Bad Inventory\") AS \"Bad Inventory\", SUM(\"Inventory Not Synced\") AS \"Inventory Not Synced\", SUM(\"Stock In Transfer\") AS \"Stock In Transfer\", SUM(\"Not Found\") AS \"Not Found\", SUM(\"Open Purchase\") AS \"Open Purchase\", SUM(\"Open Sale\") AS \"Open Sale\", SUM(\"Pending Inventory Assesment\") AS \"Pending Inventory Assesment\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'XS\' THEN inventory_qty ELSE 0 END) AS XS, SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'S\' THEN inventory_qty ELSE 0 END) AS S, SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'M\' THEN inventory_qty ELSE 0 END) AS M, SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'L\' THEN inventory_qty ELSE 0 END) AS L, SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'XL\' THEN inventory_qty ELSE 0 END) AS XL, SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) IN (\'2XL\',\'XXL\') THEN inventory_qty ELSE 0 END) AS \"2XL\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) IN (\'3XL\',\'XXXL\') THEN inventory_qty ELSE 0 END) AS \"3XL\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'4XL\' THEN inventory_qty ELSE 0 END) AS \"4XL\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'5XL\' THEN inventory_qty ELSE 0 END) AS \"5XL\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'6XL\' THEN inventory_qty ELSE 0 END) AS \"6XL\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'28\' THEN inventory_qty ELSE 0 END) AS \"28\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'30\' THEN inventory_qty ELSE 0 END) AS \"30\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'32\' THEN inventory_qty ELSE 0 END) AS \"32\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'34\' THEN inventory_qty ELSE 0 END) AS \"34\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'36\' THEN inventory_qty ELSE 0 END) AS \"36\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'38\' THEN inventory_qty ELSE 0 END) AS \"38\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'40\' THEN inventory_qty ELSE 0 END) AS \"40\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'41\' THEN inventory_qty ELSE 0 END) AS \"41\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'42\' THEN inventory_qty ELSE 0 END) AS \"42\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'43\' THEN inventory_qty ELSE 0 END) AS \"43\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'44\' THEN inventory_qty ELSE 0 END) AS \"44\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'45\' THEN inventory_qty ELSE 0 END) AS \"45\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'46\' THEN inventory_qty ELSE 0 END) AS \"46\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'47\' THEN inventory_qty ELSE 0 END) AS \"47\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'48\' THEN inventory_qty ELSE 0 END) AS \"48\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'49\' THEN inventory_qty ELSE 0 END) AS \"49\", SUM(CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) = \'50\' THEN inventory_qty ELSE 0 END) AS \"50\" FROM inventory_union GROUP BY 1, 2, 3 ) SELECT b.sku_group, CASE WHEN fs.sku_group IS NOT NULL THEN \'flagged\' ELSE \'unflagged\' END AS sku_status, c.L1_CATEGORY, c.CATEGORY, p.DAYS_SINCE_INWARD, i.inventory_status, i.inventory_location, i.\"Inventory Blocked\", i.\"Inventory Not Synced\", i.\"Stock In Transfer\", i.\"Not Found\", i.\"Open Purchase\", i.\"Open Sale\", i.\"Pending Inventory Assesment\", i.INVENTORY, i.XS, i.S, i.M, i.L, i.XL, i.\"2XL\", i.\"3XL\", i.\"4XL\", i.\"5XL\", i.\"6XL\", i.\"28\", i.\"30\", i.\"32\", i.\"34\", i.\"36\", i.\"38\", i.\"40\", i.\"41\", i.\"42\", i.\"43\", i.\"44\", i.\"45\", i.\"46\", i.\"47\", i.\"48\", i.\"49\", i.\"50\" FROM base b LEFT JOIN flagged_skus fs ON b.sku_group = fs.sku_group LEFT JOIN category_data c ON b.sku_group = c.sku_group LEFT JOIN product p ON b.sku_group = p.sku_group LEFT JOIN inventory i ON b.sku_group = i.sku_group WHERE b.sku_group IS NOT NULL and DAYS_SINCE_INWARD >180;",
                    "transaction": true
                }
            ) }}
